+fn read_bounded_output<R: Read>(
+    mut stream: R,
+    limit: usize,
+    stop: Arc<AtomicBool>,
+) -> (io::Result<()>, Vec<u8>) {
+    let mut bytes = Vec::new();
+    let mut buffer = [0_u8; 8192];
+    loop {
+        if stop.load(Ordering::Acquire) {
+            return (Ok(()), bytes);
+        }
+        let remaining = limit.saturating_sub(bytes.len()).min(buffer.len());
+        if remaining == 0 {
+            return (Ok(()), bytes);
+        }
+        match stream.read(&mut buffer[..remaining]) {
+            Ok(0) => return (Ok(()), bytes),
+            Ok(read) => {
+                bytes.extend_from_slice(&buffer[..read]);
+                if bytes.len() == limit {
+                    return (Ok(()), bytes);
+                }
+            }
+            Err(error) if error.kind() == io::ErrorKind::WouldBlock => {
+                std::thread::sleep(Duration::from_millis(5));
+            }
+            Err(error) if error.kind() == io::ErrorKind::Interrupted => {}
+            Err(error) => return (Err(error), bytes),
+        }
+    }
+}
+
+fn write_bounded_input(
+    mut stream: ChildStdin,
+    bytes: Vec<u8>,
+    stop: Arc<AtomicBool>,
+) -> io::Result<()> {
+    let mut written = 0;
+    while written < bytes.len() {
+        if stop.load(Ordering::Acquire) {
+            return Err(io::Error::new(
+                io::ErrorKind::Interrupted,
+                "request delivery cancelled",
+            ));
+        }
+        match stream.write(&bytes[written..]) {
+            Ok(0) => return Err(io::Error::from(io::ErrorKind::WriteZero)),
+            Ok(count) => written += count,
+            Err(error) if error.kind() == io::ErrorKind::WouldBlock => {
+                std::thread::sleep(Duration::from_millis(5));
+            }
+            Err(error) if error.kind() == io::ErrorKind::Interrupted => {}
+            Err(error) => return Err(error),
+        }
+    }
+    Ok(())
+}
+fn kill_process_group(child: &mut std::process::Child) {
+    unsafe {
+        libc::kill(-(child.id() as i32), libc::SIGKILL);
+    }
+}
